commits.patch:
diff --git a/libheif/color-conversion/monochrome.cc b/libheif/color-conversion/monochrome.cc
index acce06ba..982e082c 100644
--- a/libheif/color-conversion/monochrome.cc
+++ b/libheif/color-conversion/monochrome.cc
@@ -46,7 +46,7 @@ Op_mono_to_YCbCr420::state_after_conversion(const ColorState& input_state,
   output_state.colorspace = heif_colorspace_YCbCr;
   output_state.chroma = heif_chroma_420;
   output_state.set_color_bits_per_pixel(input_state.bits_per_pixel_Y);
-  output_state.bits_per_pixel_alpha = input_state.bits_per_pixel_alpha;
+  output_state.bits_per_pixel_alpha = input_state.bits_per_pixel_Y;

   states.emplace_back(output_state, SpeedCosts_OptimizedSoftware);

diff --git a/libheif/color-conversion/yuv2rgb.cc b/libheif/color-conversion/yuv2rgb.cc
index 00735274..1307ff87 100644
--- a/libheif/color-conversion/yuv2rgb.cc
+++ b/libheif/color-conversion/yuv2rgb.cc
@@ -588,12 +588,19 @@ Op_YCbCr420_to_RRGGBBaa::state_after_conversion(const ColorState& input_state,
     return {};
   }

-  // All planes, alpha included, are read as uint16_t samples.
-  if (!input_state.all_channels_have_bytes_per_sample(2)) {
+  // The three colour planes are read as uint16_t samples.
+  if (!input_state.color_channels_have_bytes_per_sample(2)) {
     return {};
   }

-  if (input_state.has_alpha() && input_state.bits_per_pixel_alpha != input_state.bits_per_pixel_Y) {
+  // The alpha plane is read at its own sample width and widened into the output
+  // samples below, so it does not have to share the colour depth: an 8-bit
+  // alpha next to a deeper colour is read directly instead of being rewritten
+  // by Op_adjust_alpha_bit_depth first, which saves a pass over the whole
+  // plane. Any other alpha depth is left to that operator.
+  if (input_state.has_alpha() &&
+      input_state.bits_per_pixel_alpha != 8 &&
+      input_state.bits_per_pixel_alpha != input_state.bits_per_pixel_Y) {
     return {};
   }

@@ -677,7 +684,10 @@ Op_YCbCr420_to_RRGGBBaa::convert_colorspace(const std::shared_ptr<const HeifPixe
       };
     }

-    if (input->get_bits_per_pixel(heif_channel_Alpha) != bpp) {
+    // The alpha samples are widened into the interleaved output below, at the
+    // sample width that state_after_conversion() offered this operation for.
+    if (input_state.bits_per_pixel_alpha != 8 &&
+        input_state.bits_per_pixel_alpha != bpp) {
       return Error{
         heif_error_Unsupported_feature,
         heif_suberror_Unspecified,
@@ -693,15 +703,23 @@ Op_YCbCr420_to_RRGGBBaa::convert_colorspace(const std::shared_ptr<const HeifPixe
   size_t out_p_stride = 0;

   const uint16_t* in_y, * in_cb, * in_cr, * in_a = nullptr;
-  size_t in_y_stride = 0, in_cb_stride = 0, in_cr_stride = 0, in_a_stride = 0;
+  const uint8_t* in_a8 = nullptr;
+  size_t in_y_stride = 0, in_cb_stride = 0, in_cr_stride = 0, in_a_stride = 0, in_a8_stride = 0;

   out_p = outimg->get_channel_memory(heif_channel_interleaved, &out_p_stride);
   in_y = (uint16_t*) input->get_channel_memory(heif_channel_Y, &in_y_stride);
   in_cb = (uint16_t*) input->get_channel_memory(heif_channel_Cb, &in_cb_stride);
   in_cr = (uint16_t*) input->get_channel_memory(heif_channel_Cr, &in_cr_stride);

+  bool alpha_is_8bit = false;
   if (has_alpha) {
-    in_a = (uint16_t*) input->get_channel_memory(heif_channel_Alpha, &in_a_stride);
+    if (input_state.bits_per_pixel_alpha == 8) {
+      alpha_is_8bit = true;
+      in_a8 = input->get_channel_memory(heif_channel_Alpha, &in_a8_stride);
+    }
+    else {
+      in_a = (uint16_t*) input->get_channel_memory(heif_channel_Alpha, &in_a_stride);
+    }
   }

   int maxval = (1 << bpp) - 1;
@@ -744,8 +762,16 @@ Op_YCbCr420_to_RRGGBBaa::convert_colorspace(const std::shared_ptr<const HeifPixe
       out_p[y * out_p_stride + bytesPerPixel * x + 5 - le] = (uint8_t) (b & 0xff);

       if (has_alpha) {
-        out_p[y * out_p_stride + 8 * x + 6 + le] = (uint8_t) (in_a[y * in_a_stride / 2 + x] >> 8);
-        out_p[y * out_p_stride + 8 * x + 7 - le] = (uint8_t) (in_a[y * in_a_stride / 2 + x] & 0xff);
+        uint16_t a;
+        if (alpha_is_8bit) {
+          uint16_t a8 = in_a8[y * in_a8_stride + x];
+          a = static_cast<uint16_t>((a8 << (bpp - 8)) | (a8 >> (16 - bpp)));
+        }
+        else {
+          a = in_a[y * in_a_stride / 2 + x];
+        }
+        out_p[y * out_p_stride + 8 * x + 6 + le] = (uint8_t) (a >> 8);
+        out_p[y * out_p_stride + 8 * x + 7 - le] = (uint8_t) (a & 0xff);
       }
     }
   }
